new TreePathScanner<Void, Void>() {

    /**
     * 1 = corpo de método/lambda (Msg.t), 2 = campo/enum/bloco estático (Msg.k, adiado), 0 = fora (anotação, case, prompt).
     */
    int context(TreePath p) {
        for (TreePath q = p.getParentPath(); q != null; q = q.getParentPath()) {
            Tree t = q.getLeaf();
            if (t instanceof AnnotationTree)
                return 0;
            // rótulo de case (precisa ser constante)
            if (t instanceof ConstantCaseLabelTree)
                return 0;
            if (t instanceof CaseTree c && c.getExpressions().contains(directChild(q, p)))
                return 0;
            if (t instanceof MethodTree m) {
                String n = m.getName().toString().toLowerCase();
                return ((n.contains("prompt") && !n.contains("suggest") && !n.contains("quick") && !n.contains("example") && !n.contains("chip")) || n.contains("systemmessage") || n.contains("instruction")) ? 0 : 1;
            }
            if (t instanceof LambdaExpressionTree)
                return 1;
            // campo ou constante de enum
            if (t instanceof VariableTree v && q.getParentPath() != null && q.getParentPath().getLeaf() instanceof ClassTree)
                return 2;
            // bloco estático
            if (t instanceof BlockTree && q.getParentPath() != null && q.getParentPath().getLeaf() instanceof ClassTree)
                return 2;
            if (t instanceof ClassTree)
                return 0;
        }
        return 0;
    }

    boolean deferred(TreePath p) {
        // notificações ficam no banco: guardar o marcador, não o texto
        for (TreePath q = p.getParentPath(); q != null; q = q.getParentPath()) {
            Tree t = q.getLeaf();
            if (t instanceof MethodInvocationTree mi) {
                ExpressionTree sel = mi.getMethodSelect();
                String name = sel instanceof MemberSelectTree ms ? ms.getIdentifier().toString() : sel.toString();
                if (name.equals("notify") || name.equals("notifyAll") || name.equals("notifyOnce"))
                    return true;
            }
            if (t instanceof MethodTree || t instanceof LambdaExpressionTree || t instanceof ClassTree)
                return false;
        }
        return false;
    }

    String reason = "";

    Tree directChild(TreePath ancestor, TreePath leaf) {
        TreePath q = leaf;
        while (q.getParentPath() != null && q.getParentPath() != ancestor) q = q.getParentPath();
        return q.getLeaf();
    }

    boolean skippedCall(TreePath p) {
        for (TreePath q = p.getParentPath(); q != null; q = q.getParentPath()) {
            Tree t = q.getLeaf();
            if (t instanceof MethodInvocationTree mi) {
                ExpressionTree sel = mi.getMethodSelect();
                String name = sel instanceof MemberSelectTree ms ? ms.getIdentifier().toString() : sel.toString();
                String recv = sel instanceof MemberSelectTree ms ? ms.getExpression().toString() : "";
                if (SKIP_METHODS.contains(name) || SKIP_RECEIVERS.contains(recv) || ((recv.endsWith("log") || recv.startsWith("log.")) && Set.of("info", "warn", "debug", "error", "trace").contains(name))) {
                    reason = "call:" + (recv.isEmpty() ? "" : recv + ".") + name;
                    return true;
                }
                if (name.equals("put") || name.equals("putIfAbsent")) {
                    if (mi.getArguments().size() >= 1 && directChild(q, p) == mi.getArguments().get(0)) {
                        reason = "mapkey";
                        return true;
                    }
                }
                if (name.equals("of") || name.equals("ofEntries") || name.equals("entry")) {
                    int idx = mi.getArguments().indexOf(directChild(q, p));
                    // chave do mapa
                    if ((recv.equals("Map") || name.equals("entry")) && idx % 2 == 0) {
                        reason = "mapkey";
                        return true;
                    }
                    boolean anyStr = mi.getArguments().stream().anyMatch(a -> a instanceof LiteralTree l && l.getKind() == Tree.Kind.STRING_LITERAL);
                    boolean allWords = anyStr && mi.getArguments().stream().allMatch(a -> !(a instanceof LiteralTree l) || l.getKind() != Tree.Kind.STRING_LITERAL || (!((String) l.getValue()).trim().contains(" ") && Character.isLowerCase(((String) l.getValue()).trim().charAt(0))));
                    // lista de palavras-chave
                    if ((recv.equals("List") || recv.equals("Set")) && allWords) {
                        reason = "keywords";
                        return true;
                    }
                }
            }
            if (t instanceof BinaryTree b && b.getKind() != Tree.Kind.PLUS) {
                reason = "compare";
                return true;
            }
            // comparações
            if (t instanceof NewClassTree nc && INTERNAL_EX.contains(nc.getIdentifier().toString())) {
                reason = "internal-ex";
                return true;
            }
            if (t instanceof MethodTree || t instanceof LambdaExpressionTree || t instanceof ClassTree)
                return false;
        }
        return false;
    }

    @Override
    public Void visitLiteral(LiteralTree lit, Void v) {
        if (lit.getKind() != Tree.Kind.STRING_LITERAL || consumed.contains(lit))
            return null;
        TreePath p = getCurrentPath();
        String text = (String) lit.getValue();
        // text block = prompt
        long s0 = pos.getStartPosition(cu, lit);
        // text block = prompt
        if (src.startsWith("\"\"\"", (int) s0))
            return null;
        int ctx = context(p);
        reason = "";
        if (ctx == 0 || skippedCall(p)) {
            if (natural(text))
                skipped.add(rel + ":" + lm.getLineNumber(s0) + " [" + (ctx == 0 ? "ctx0" : reason) + "] " + text);
            return null;
        }
        String fn = ctx == 2 || deferred(p) ? "Msg.k" : "Msg.t";
        if (text.contains("\n") || PROMPT.matcher(text).find()) {
            skipped.add(rel + ":" + lm.getLineNumber(s0) + " [prompt] " + text.replace("\n", "⏎"));
            return null;
        }
        // sobe a cadeia de concatenação
        TreePath top = p;
        while (top.getParentPath() != null && top.getParentPath().getLeaf() instanceof BinaryTree b && b.getKind() == Tree.Kind.PLUS) top = top.getParentPath();
        if (top.getLeaf() != lit) {
            List<ExpressionTree> ops = new ArrayList<>();
            flatten((ExpressionTree) top.getLeaf(), ops);
            for (ExpressionTree o : ops) consumed.add(o);
            consumed.add(top.getLeaf());
            boolean any = false;
            for (ExpressionTree o : ops) if (o instanceof LiteralTree l && l.getKind() == Tree.Kind.STRING_LITERAL && natural((String) l.getValue()))
                any = true;
            if (!any)
                return null;
            int firstStr = -1;
            for (int i = 0; i < ops.size(); i++) if (ops.get(i) instanceof LiteralTree l && l.getKind() == Tree.Kind.STRING_LITERAL) {
                firstStr = i;
                break;
            }
            StringBuilder pat = new StringBuilder();
            List<String> args = new ArrayList<>();
            if (firstStr > 0) {
                StringBuilder a = new StringBuilder("(");
                for (int i = 0; i < firstStr; i++) a.append(i > 0 ? " + " : "").append(text(ops.get(i)));
                a.append(")");
                args.add(a.toString());
                pat.append("{0}");
            }
            for (int i = Math.max(firstStr, 0); i < ops.size(); i++) {
                ExpressionTree o = ops.get(i);
                if (o instanceof LiteralTree l && l.getKind() == Tree.Kind.STRING_LITERAL)
                    pat.append(mf((String) l.getValue()));
                else if (o instanceof LiteralTree l && l.getKind() == Tree.Kind.CHAR_LITERAL)
                    pat.append(mf(String.valueOf(l.getValue())));
                else {
                    pat.append("{").append(args.size()).append("}");
                    args.add(text(o));
                }
            }
            String key = keyFor(pat.toString(), nsF, rel);
            found.add(new Found(rel, lm.getLineNumber(s0), key, pat.toString()));
            edits.add(new Edit(pos.getStartPosition(cu, top.getLeaf()), pos.getEndPosition(cu, top.getLeaf()), fn + "(\"" + key + "\"" + (args.isEmpty() ? "" : ", " + String.join(", ", args)) + ")"));
            return null;
        }
        if (!natural(text))
            return null;
        String key = keyFor(mf(text), nsF, rel);
        found.add(new Found(rel, lm.getLineNumber(s0), key, text));
        edits.add(new Edit(s0, pos.getEndPosition(cu, lit), fn + "(\"" + key + "\")"));
        return null;
    }

    void flatten(ExpressionTree e, List<ExpressionTree> out) {
        if (e instanceof BinaryTree b && b.getKind() == Tree.Kind.PLUS) {
            flatten(b.getLeftOperand(), out);
            flatten(b.getRightOperand(), out);
        } else
            out.add(e);
    }

    String text(Tree t) {
        return src.substring((int) pos.getStartPosition(cu, t), (int) pos.getEndPosition(cu, t));
    }
}.scan
